// ===== AES decrypt functions =====
pub fn aes_decrypt(encoded: &[u8], key: &[u8; 32], nonce: &[u8; 12]) -> Vec<u8> {
    let cipher = Aes256Gcm::new_from_slice(key).unwrap();
    let n = Nonce::from_slice(nonce);
    cipher.decrypt(n, encoded).unwrap_or_default()
}

pub fn aes_to_cstring(encoded: &[u8], key: &[u8; 32], nonce: &[u8; 12]) -> std::ffi::CString {
    let decoded = aes_decrypt(encoded, key, nonce);
    unsafe { std::ffi::CString::from_vec_unchecked(decoded) }
}

pub fn aes_decode_stack(encoded: &[u8], key: &[u8; 32], nonce: &[u8; 12], buf: &mut [u8; 256]) -> usize {
    let decoded = aes_decrypt(encoded, key, nonce);
    let len = decoded.len().min(255);
    buf[..len].copy_from_slice(&decoded[..len]);
    buf[len] = 0;
    len
}
